//============================================================================// ORCA v6.0 ZEN — Phoenix AME (Adaptive Matrix Engine)// Peak Performance: 4 TOPS @ 3.2GHz (INT8 dense-equivalent)// Target Process: 5nm// Area Estimate: ~2.0 mm2 (AME only)// Power Estimate: <3W (AME only)//// Features:// - Sparse matrix acceleration (2:4 structured sparsity, CSR format)// - 16 sparse blocks x 8x8 = 1024 MACs// - Skip-zero logic for power efficiency// - Dynamic shape support for irregular GEMM// - MoE / Transformer sparse layer acceleration//============================================================================`ifndef ORCA_AME_V6_SV`define ORCA_AME_V6_SV`include  orca_params.sv  `include  orca_pkg.sv  module orca_ame_v6 #  ( parameter int NUM_BLOCKS     = 16    , parameter int BLOCK_DIM      = 8    , parameter int SPARSE_RATIO   = 2         // 2:4 structured sparsity    , parameter int ACC_WIDTH      = 32    , parameter int IDX_WIDTH      = 16        // CSR index width  )  (    input  logic        clk    , input  logic        rst_n    // --------------------------------------------------------------------------    // Sparse command interface    // --------------------------------------------------------------------------    , input  logic [63:0] sparse_cmd    , input  logic        sparse_cmd_valid    , output logic        sparse_cmd_ready    // --------------------------------------------------------------------------    // CSR data interface (loaded via DMA from DDR)    // --------------------------------------------------------------------------    , input  logic [31:0] csr_row_ptr [0:127]     // Row pointers    , input  logic [15:0] csr_col_idx [0:1023]    // Column indices    , input  logic signed [7:0] csr_values [0:1023]  // Non-zero values    // --------------------------------------------------------------------------    // Dense vector input    // --------------------------------------------------------------------------    , input  logic signed [7:0] dense_vec [0:255]    , input  logic              vec_valid    // --------------------------------------------------------------------------    // Output    // --------------------------------------------------------------------------    , output logic signed [ACC_WIDTH-1:0] sparse_result [0:127]    , output logic                        result_valid    // --------------------------------------------------------------------------    // Status    // --------------------------------------------------------------------------    , output logic [63:0] ame_ops_counter  );  typedef enum logic [2:0]  {    AME_IDLE        = 3'd0    , AME_LOAD_CSR    = 3'd1    , AME_COMPUTE_BLOCK = 3'd2    , AME_SKIP_ZERO   = 3'd3    , AME_STORE       = 3'd4    , AME_DONE        = 3'd5  } ame_state_t;  ame_state_t state, next_state;  // Block-sparse compute units  logic signed [ACC_WIDTH-1:0] block_acc [0:NUM_BLOCKS-1][0:BLOCK_DIM-1];  logic [7:0] row_counter;  logic [10:0] nnz_counter;  logic [63:0] ops_cnt;  // Skip-zero controller  logic [BLOCK_DIM-1:0] row_nnz_mask;  logic                 row_is_empty;  always_ff @(posedge clk or negedge rst_n) begin    if (!rst_n) begin      state <= AME_IDLE;      row_counter <= '0;      nnz_counter <= '0;      ops_cnt <= '0;      result_valid <= 1'b0;    end else begin      state <= next_state;      case (state)        AME_LOAD_CSR: begin          row_counter <= row_counter + 1;          nnz_counter <= csr_row_ptr[row_counter+1] - csr_row_ptr[row_counter];        end        AME_COMPUTE_BLOCK: begin          // Only compute non-zero elements          if (nnz_counter > 0) begin            for (int b = 0; b < NUM_BLOCKS; b = b + 1) begin              for (int d = 0; d < BLOCK_DIM; d = d + 1) begin                if (csr_col_idx[nnz_counter] < 256) begin                  block_acc[b][d] <= block_acc[b][d] +                    csr_values[nnz_counter] *                    dense_vec[csr_col_idx[nnz_counter]];                end              end            end            nnz_counter <= nnz_counter - 1;            ops_cnt <= ops_cnt + NUM_BLOCKS * BLOCK_DIM;          end        end        AME_SKIP_ZERO: begin          // Fast-forward through empty rows          if (row_is_empty) row_counter <= row_counter + 1;        end        AME_STORE: begin          for (int b = 0; b < NUM_BLOCKS; b = b + 1) begin            for (int d = 0; d < BLOCK_DIM; d = d + 1) begin              sparse_result[b*BLOCK_DIM + d] <= block_acc[b][d];              block_acc[b][d] <= '0;            end          end          result_valid <= 1'b1;        end        AME_DONE: begin          result_valid <= 1'b0;        end      endcase    end  end  // Next-state logic  always_comb begin    next_state = state;    case (state)      AME_IDLE:           if (sparse_cmd_valid) next_state = AME_LOAD_CSR;      AME_LOAD_CSR:       next_state = (nnz_counter == 0) ? AME_SKIP_ZERO : AME_COMPUTE_BLOCK;      AME_COMPUTE_BLOCK:  next_state = (nnz_counter == 0) ? AME_STORE : AME_COMPUTE_BLOCK;      AME_SKIP_ZERO:      next_state = (row_counter >= 128) ? AME_STORE : AME_LOAD_CSR;      AME_STORE:          next_state = AME_DONE;      AME_DONE:           next_state = AME_IDLE;      default:            next_state = AME_IDLE;    endcase  end  // Skip-zero detection  assign row_is_empty = (csr_row_ptr[row_counter+1] == csr_row_ptr[row_counter]);  // Outputs  assign sparse_cmd_ready = (state == AME_IDLE);  assign ame_ops_counter = ops_cnt;endmodule // orca_ame_v6`endif // ORCA_AME_V6_SV